const fs=require('fs'),crypto=require('crypto');
(async()=>{let outputs=[];for(const name of ['base','modified']){const d=await require('./'+name+'.js')({wasmBinary:fs.readFileSync(name+'.wasm'),print:()=>{},printErr:()=>{}});if(name==='modified'){const marker=d._novalure_lgpl_relink_marker();console.log('MARKER',marker);if(marker!==0x1234abcd)throw Error('wrong marker')}d.FS.writeFile('/input.heic',fs.readFileSync('example.heic'));let code;try{code=d.callMain(['/input.heic','/output.rgba'])}catch(e){code=e.status??-1}if(code!==0)throw Error(name+' decode failed '+code);const out=d.FS.readFile('/output.rgba'),dv=new DataView(out.buffer,out.byteOffset),w=dv.getUint32(0,true),h=dv.getUint32(4,true),sha=crypto.createHash('sha256').update(out).digest('hex');console.log('DECODE',name,w,h,out.length,sha);if(w!==1280||h!==854||out.length!==8+w*h*4)throw Error('bad output');outputs.push(sha);process.exitCode=0}if(outputs[0]!==outputs[1])throw Error('different image output');console.log('RELINK_TEST_PASS')})().catch(e=>{console.error(e);process.exitCode=1});
